operators.source:
let sum(a:int, b:int) = { (a + b) * 2 - a / b }
let rest(a:int, b:int) = { a % b }
let compare(a:int, b:int) = { a <= b || a >= b && !(a < b) }
let given(s:string?) = { s? }
let negative(a:int) = { -a }
let upTo(a:int) = { 1..a }
let through(a:int) = { 1..=a }

